with open('scripts/chunks/chunk_10.json', 'r', encoding='utf-8') as f:
    chunk_items = json.load(f)

missing = [x['key'] for x in chunk_items if x['key'] not in trans_10]
extra = [k for k in trans_10 if k not in {x['key'] for x in chunk_items}]

print(f"Total chunk_10 items: {len(chunk_items)}")
print(f"Translated items: {len(trans_10)}")
print(f"Missing keys: {len(missing)} -> {missing}")
print(f"Extra keys: {len(extra)} -> {extra}")

if not missing and not extra:
    with open('scripts/chunks/trans_chunk_10.json', 'w', encoding='utf-8') as f:
        json.dump(trans_10, f, indent=2, ensure_ascii=False)
    print("SUCCESS: Saved scripts/chunks/trans_chunk_10.json")
